function findMaxLength(nums) {
  let best = 0;
  for (let start = 0; start < nums.length; start++) {
    let zeros = 0, ones = 0;
    for (let end = start; end < nums.length; end++) {
      if (nums[end] === 0) zeros++;
      else ones++;
      if (zeros === ones) best = Math.max(best, end - start + 1);
    }
  }
  return best;
}

