function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 12);
  const style = rand();
  // A bias towards ones (or zeros) makes the longest balanced run vary in where it sits.
  const chance = style < 0.1 ? 0.95 : style < 0.2 ? 0.05 : style < 0.6 ? 0.5 : 0.4 + rand() * 0.2;
  const nums = [];
  while (nums.length < n) {
    if (style >= 0.6 && rand() < 0.1) {
      // A block of one value, as in [1,1,1,0,0,0].
      const value = rand() < 0.5 ? 0 : 1;
      const block = 1 + Math.floor(rand() * (size === 'large' ? 200 : 4));
      for (let k = 0; k < block && nums.length < n; k++) nums.push(value);
    } else {
      nums.push(rand() < chance ? 1 : 0);
    }
  }
  return [nums];
}
